import java.util.*;class Solution{List<String>o=new ArrayList<>();void f(String s,int p,long v,long last,String e,long t){if(p==s.length()){if(v==t)o.add(e);return;}long n=0;for(int i=p;i<s.length();i++){if(i>p&&s.charAt(p)=='0')break;n=n*10+s.charAt(i)-'0';String x=s.substring(p,i+1);if(p==0)f(s,i+1,n,n,x,t);else{f(s,i+1,v+n,n,e+"+"+x,t);f(s,i+1,v-n,-n,e+"-"+x,t);f(s,i+1,v-last+last*n,last*n,e+"*"+x,t);}}}public List<String> addOperators(String s,int t){f(s,0,0,0,"",t);return o;}}
